package com.project7.localmanager;
import java.io.*;import java.util.*;
final class TreasureWishResolver {
 static final class Decision {final HistoryCatalog.Leaf source;final HistoryCatalog.Edge outer;final boolean target;final int scope,next;Decision(HistoryCatalog.Leaf s,HistoryCatalog.Edge o,boolean t,int id,int n){source=s;outer=o;target=t;scope=id;next=n;}}
 static Decision resolve(byte[]profile,byte[]state,int planScope,int planTarget,Random random)throws Exception{WishCatalog catalog=WishCatalog.ready();int id=WishChoosePolicy.scope(state);List<Integer>ctr=WishChoosePolicy.choice(state,id);Map<?,?>row=WishCatalog.row(catalog.wish,id);int target=ctr.get(1)==0?DynamicCatalog.num(row.get("treasure_id")):ctr.get(1);WishCatalog.need(id==planScope&&target==planTarget,"pending wish target changed");int misses=WishChoosePolicy.step(state,id);
  WishProbability.Fraction p=WishProbability.wish(row.get("begin_rate"),row.get("step_rate"),DynamicCatalog.num(row.get("times")),misses);HistoryCatalog.Leaf chosen;HistoryCatalog.Edge outer=null;HistoryCatalog.Leaf desired=ctr.get(1)==0?WishSource.pick(row,"reward",new Random(0)):WishSource.pick(WishCatalog.row(catalog.choose,target),"rewards",new Random(0));
  if(WishProbability.hit(random,p))chosen=ctr.get(1)==0?WishSource.pick(row,"reward",random):WishSource.pick(WishCatalog.row(catalog.choose,target),"rewards",random);else{HistoryCatalog graph=HistoryDrawPolicy.dynamicCatalog();outer=graph.specs.get(5).base.pick(random);chosen=graph.leaves.get(graph.random.get(outer.target).pick(random).target);}
  boolean hit=chosen.kind.equals(desired.kind)&&chosen.id==desired.id&&chosen.quality==desired.quality&&(desired.design()==null||Arrays.equals(chosen.design(),desired.design()));WishCatalog.need(hit||misses<Integer.MAX_VALUE,"wish counter overflow");return new Decision(chosen,outer,hit,id,hit?0:misses+1);
 }
 static HistoryCatalog.Leaf duplicate(byte[]profile,HistoryCatalog.Leaf source)throws Exception{WishCatalog c=WishCatalog.ready();if(!source.kind.equals("treasure")||!c.exclusive.containsKey(source.id))return source;Map<?,?>binding=WishCatalog.row(c.exclusive,source.id);if(source.quality!=DynamicCatalog.num(binding.get("quality"))||!owns(profile,source.id,source.quality))return source;return new HistoryCatalog.Leaf(source.common,"item",DynamicCatalog.num(binding.get("reget_item")),DynamicCatalog.num(binding.get("reget_count")),1,0,null);}
 static boolean owns(byte[]p,int id,int quality)throws Exception{List<byte[]>items=new ArrayList<>();byte[]inv=BsonLite.documentValue(p,"inv");if(inv!=null)items.addAll(LocalResourceEngine.array(BsonLite.arrayValue(inv,"items")));byte[]manager=BsonLite.documentValue(p,"heromgr");if(manager!=null)for(byte[]pair:LocalResourceEngine.array(BsonLite.arrayValue(manager,"hrs"))){byte[]hero=BsonLite.documentValue(pair,"1"),ti=BsonLite.documentValue(hero,"ti");if(ti!=null)items.addAll(LocalResourceEngine.array(BsonLite.arrayValue(ti,"items")));}for(byte[]item:items){byte[]tr=BsonLite.documentValue(item,"tr");if(Integer.valueOf(id).equals(BsonLite.intValue(item,"i"))&&tr!=null&&Integer.valueOf(quality).equals(BsonLite.intValue(tr,"cl")))return true;}return false;}
}
